    var inputs = sessionData && sessionData.user_inputs;
    if (!inputs) {
      return { valid: false, code: 400, description: "user_inputs missing from session" };
    }
    var required = ["item_id", "provider_id", "bpp_id", "bpp_uri", "pan", "fullName", "dob", "constitution", "businessPan", "doi", "natureOfBusiness", "annualTurnover", "businessPincode", "bureauConsent"];
