async function generatePayload(defaultPayload, sessionData) {
  const { user_inputs } = sessionData;
defaultPayload.context = defaultPayload.context || {};

    // Extract values from user_inputs
    const bppId = user_inputs?.bpp_id;
    const bppUri = user_inputs?.bpp_uri;

    // Validate required fields
    if (!bppId || !bppUri) {
      console.log("bpp_id or bpp_uri missing in user_inputs");
      return defaultPayload;
    }

  defaultPayload.context.bpp_id = bppId;
  defaultPayload.context.bpp_uri = bppUri;
  const provider = user_inputs?.provider;
  const items = user_inputs?.items;
  const fulfillments = user_inputs?.fulfillments;

  if (!provider?.id) {
    throw new Error("provider.id missing in user_inputs");
  }

  if (!Array.isArray(items) || items.length === 0) {
    throw new Error("items missing in user_inputs");
  }

  if (!Array.isArray(fulfillments) || fulfillments.length === 0) {
    throw new Error("fulfillments missing in user_inputs");
  }

