function validate(targetPayload, sessionData) {
  try {

    const context = targetPayload?.context;
    if (!context || context.action !== "select") {
      return {
        valid: false,
        code: 400,
        description: "context.action must be select"
      };
    }


    const order = targetPayload?.message?.order;

    if (!order?.provider?.id) {
      return {
        valid: false,
        code: 400,
        description: "message.order.provider.id is required"
      };
    }

    if (!Array.isArray(order.items) || order.items.length === 0) {
      return {
        valid: false,
        code: 400,
        description: "message.order.items is required"
      };
    }

    if (!Array.isArray(order.fulfillments) || order.fulfillments.length === 0) {
      return {
        valid: false,
        code: 400,
        description: "message.order.fulfillments is required"
      };
    }

    const inputs = sessionData?.user_inputs;

    if (inputs) {
      // Provider validation
      if (
        inputs.provider?.id &&
        order.provider.id !== inputs.provider.id
      ) {
        return {
          valid: false,
          code: 400,
          description:
            "message.order.provider.id does not match user_inputs.provider.id"
        };
      }

      // Items validation
      if (Array.isArray(inputs.items)) {
        if (order.items.length !== inputs.items.length) {
          return {
            valid: false,
            code: 400,
            description:
              "message.order.items count does not match user_inputs.items"
          };
        }

        for (let i = 0; i < inputs.items.length; i++) {
          if (order.items[i].id !== inputs.items[i].id) {
            return {
              valid: false,
              code: 400,
              description: `message.order.items[${i}].id does not match user_inputs.items[${i}].id`
            };
          }
        }
      }

      // Fulfillments validation
      if (Array.isArray(inputs.fulfillments)) {
        if (order.fulfillments.length !== inputs.fulfillments.length) {
          return {
            valid: false,
            code: 400,
            description:
              "message.order.fulfillments count does not match user_inputs.fulfillments"
          };
        }

        for (let i = 0; i < inputs.fulfillments.length; i++) {
          if (order.fulfillments[i].id !== inputs.fulfillments[i].id) {
            return {
              valid: false,
              code: 400,
              description: `message.order.fulfillments[${i}].id does not match user_inputs.fulfillments[${i}].id`
            };
          }
        }
      }
    }

    return {
      valid: true,
      code: 200,
      description: "Valid request"
    };
  } catch (error) {
    return {
      valid: false,
      code: 500,
      description: "Internal validation error"
    };
  }
}

